(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["vi"] = {"ui":{"skip":"Bỏ qua, đến nội dung","back":"← Quay lại AI-gile","lang.button":"Ngôn ngữ: {name}","lang.dialog":"Chọn một ngôn ngữ","lang.search":"Tìm ngôn ngữ","lang.none":"Không có ngôn ngữ nào khớp","lang.notYet":"{name} chưa được dịch","theme.aria":"Đổi giao diện: sáng, tối hoặc đen","theme.toLight":"Chuyển sang giao diện sáng","theme.toDark":"Chuyển sang giao diện tối","theme.toBlack":"Chuyển sang giao diện đen (đen tuyền, dịu mắt trên màn hình OLED)","words.underline":"Gạch chân những từ này trên trang","words.underlineHelp":"Di chuột hoặc chạm vào một từ có gạch chấm để xem nghĩa của nó.","words.col.todo":"Các thẻ được chọn cho lúc này: nhóm sẽ bắt đầu với những thẻ này tiếp theo.","words.col.doing":"Một AI đang làm thẻ này ngay lúc này.","words.col.review":"Một AI đã làm xong; một AI khác kiểm tra trước khi đến tay bạn.","words.col.verify":"Đang chờ bạn: hãy thử và cho biết nó có chạy không.","words.col.team":"Ghi chú hoặc câu trả lời của bạn, đang chờ nhóm nhận.","words.col.done":"Đã xong và được chấp nhận.","index.title":"AI-gile: nhóm lập trình AI của bạn, trên một bảng","index.description":"AI-gile là bảng kanban cho các nhóm lập trình bằng AI. Họ làm việc khi bạn ngủ; bạn chỉ nhận một chồng ngắn những việc cần quyết định, thử và chấp nhận.","hero.logoAlt":"Biểu tượng bảng AI-gile","hero.h1.html":"Nhóm lập trình AI của bạn, trên một&nbsp;bảng.","hero.alpha":"🐣 Tiền alpha kín","hero.alphaTitle":"Còn sớm và chưa xong: cảm ơn bạn đã thử!","hero.lede":"Họ làm trong lúc bạn ngủ. Sáng ra bạn nhận một chồng ngắn: vài câu hỏi, vài thứ cần thử, một hai viên kim cương tím. Bấm, chấp nhận, rồi quay lại với ly cà phê.","dl.windows":"Ứng dụng Windows","dl.browser":"Chạy trong trình duyệt","dl.messenger":"📱 Messenger cho điện thoại","dl.soon":"Sắp ra mắt","dl.notify":"🔔 Báo cho tôi khi mở","dl.notifySmall":"Alpha hoặc beta","hero.secondary":"Agile, nhưng nhóm không bao giờ cần cà phê họp đứng. (Họ vẫn họp đứng thôi.)","pitch.h2":"AI-gile trong bao nhiêu từ tùy bạn","pitch.lede":"Chọn một độ dài, từ một từ đến 144. Mỗi độ dài là một bản mô tả riêng, viết cho đúng cỡ đó. Kéo thanh trượt hoặc dùng phím mũi tên.","pitch.rangeLabel":"Độ dài tính bằng từ","pitch.dice":"🎲 một bản khác","pitch.words.one":"{n} từ","pitch.words.other":"{n} từ","pitch.letters.one":"{n} chữ cái","pitch.letters.other":"{n} chữ cái","pitch.chars.one":"{n} ký tự","pitch.chars.other":"{n} ký tự","count.line.html.one":"{n} thẻ trên bảng ngay lúc này","count.line.html.other":"{n} thẻ trên bảng ngay lúc này","people.humans.html.one":"👥 {n} người","people.humans.html.other":"👥 {n} người","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agent","people.working.html.one":"⚡ {n} đang làm việc ngay lúc này","people.working.html.other":"⚡ {n} đang làm việc ngay lúc này","pre.title":"AI-gile: có gì đó đang được xây","pre.description":"Có gì đó đang được xây ở đây: một bảng nơi các nhóm AI xây những gì bạn yêu cầu, và dạy bạn trong lúc làm. Hiện là bản tiền alpha kín cùng bạn bè.","pre.h1":"Có gì đó đang được xây ở đây. 🤫","pre.line":"Một bảng nơi các nhóm AI xây những gì bạn yêu cầu, và dạy bạn trong lúc làm. Hiện là bản tiền alpha kín cùng bạn bè.","pre.btn":"🔔 Báo cho tôi khi mở","pre.peek":"Sau lớp kính: bảng thật, trực tiếp. Mỗi thẻ là một thanh màu.","pre.peekFake":"Sau lớp kính: một bảng đang làm việc trông như thế này.","pre.night":"🌙 Người gác đêm đang phụ trách · 😴 con người đang nghỉ ngơi","features.aria":"Nó làm gì","f.pile.h":"Một chồng dành cho bạn","f.pile.html":"<b>Cho bạn</b> gom mọi thứ đang chờ bạn ở tất cả dự án: câu hỏi, thứ cần thử, việc chỉ con người làm được. Hàng đợi cho biết việc tiếp theo là gì và mất bao lâu.","f.sleep.h":"Những nhóm làm việc khi bạn ngủ","f.sleep.p":"Mỗi dự án có một trưởng nhóm và một nhóm agent AI. Viết bình luận vào thẻ, nhóm sẽ thức dậy, làm việc, rồi giao lại kèm các bước mà một người mệt mỏi cũng làm theo được.","f.tester.h":"Một người kiểm thử AI xem trước","f.tester.p":"Trước khi gì đó đến tay bạn, người kiểm thử làm theo các bước trong một bản sao của ứng dụng và cho xem điều đã thấy, kèm ảnh chụp màn hình. Lướt qua những thẻ đã đạt và chấp nhận bằng một cú bấm.","f.proof.h":"Bằng chứng, không phải lời hứa","f.proof.p":"Mỗi lần bàn giao đều cho thấy điều gì đã đổi: các tệp, phần khác biệt, ảnh chụp màn hình. Không cần mở từng ứng dụng để xem đã xong chưa.","f.chat.h":"Trò chuyện với các trưởng nhóm","f.chat.p":"Một thanh bên kiểu Discord: mỗi dự án một biểu tượng, kim cương tím cho việc cần bạn. Nhắn cho trưởng nhóm một ý tưởng; họ biến nó thành thẻ và kế hoạch, kèm nút ✅ Bắt đầu.","f.tidy.h":"Tự giữ cho gọn gàng","f.tidy.p":"Các thẻ liên quan gộp thành một, tiêu đề rối được sửa lại, và phần kiểm tra token giữ cho mã gọn nhẹ. Ít thứ phải chuyển qua lại, ít thứ phải nghĩ hơn.","f.private.h":"Của bạn, trên máy tính của bạn","f.private.li1":"Bảng chạy ngay trên máy của bạn và chỉ trả lời bạn.","f.private.li2":"Tin nhắn riêng giữa mọi người được mã hóa đầu cuối.","f.private.li3":"Không tài khoản, không trình theo dõi, không cookie.","f.lang.h":"Bằng ngôn ngữ của bạn","f.lang.p":"Hơn 120 ngôn ngữ, từ tiếng Hà Lan, xứ Wales và Nhật đến tiếng cướp biển, Yoda và Klingon, kèm nút chuyển nhanh về tiếng Anh cho các thuật ngữ chuyên ngành.","f.service.h":"Từ một ý tưởng đến một dịch vụ thật","f.service.p":"Đã làm ra thứ gì đó với AI và giờ có người dùng? Đánh dấu nó là dịch vụ và bảng sẽ giúp bạn vận hành nó thật tốt: kiểm tra uptime, trang trạng thái công khai, sự cố có bản tổng kết, thay đổi cần một lần Go, sao lưu được kiểm tra hằng ngày. Phần Trợ giúp hướng dẫn từng bước khi bạn làm tới.","msgr.h2":"AI-gile Messenger: cả đội trong túi bạn","msgr.p1":"Trò chuyện với đội AI của bạn mà không cần mở bảng. Nhắn tin với các trưởng dự án và bạn bè, xem các bước kiểm thử của một thẻ và trả lời, tất cả ngay trên điện thoại.","msgr.p2":"Để ghép nối, hãy quét mã QR trên bảng của bạn. Lần đầu dùng? Một cuộc trò chuyện demo thân thiện sẽ dẫn bạn đi một vòng.","msgr.when":"Android trước, sau đó là bản web cho điện thoại và iPhone.","msgr.who":"Trưởng dự án của bạn","msgr.b1":"Bản sửa chế độ tối đã xong. Bạn muốn xem các bước kiểm thử không?","msgr.b2":"Có, cho mình xem nhé!","msgr.b3":"1. Mở Cài đặt. 2. Chọn Tối. Trông ổn chưa?","tl.aria":"Dòng thời gian từ cuộc trò chuyện đầu tiên đến lộ trình","tl.h2":"Từ cuộc trò chuyện đầu tiên đến điều tiếp theo","tl.lede":"Ngày giờ thật, theo múi giờ của bạn. Sau hôm nay là kế hoạch, không hứa ngày nào.","tl.today":"Hôm nay","tl.planned":"dự kiến","tl.doing":"đang làm","tl.cards.one":"{n} thẻ","tl.cards.other":"{n} thẻ","join.h2":"Cùng tham gia","join.lede":"AI-gile đang được xây bởi một gã râu ria lập dị có AuDHD và vài trận chiến với sức khỏe tinh thần, cùng rất nhiều agent kiên nhẫn. Hiện còn riêng tư, trong bản alpha kín với bạn bè. Muốn thử khi nó mở ra không?","join.btn":"Đăng ký quan tâm","join.small":"Chúng tôi sẽ gửi email cho bạn, không gì khác","footer.tag":"AI-gile. Không trình theo dõi, không cookie, không cà phê họp đứng.","footer.licence":"Giấy phép doanh nghiệp","footer.status":"Trạng thái","footer.privacy":"Chúng tôi giữ những gì","footer.thanks":"Cuộc gọi nhờ có ChilledChat","form.sending":"Đang gửi…","form.failed":"Không được rồi: hãy thử lại sau.","form.offline":"Không kết nối được với AI-gile: hãy thử lại sau.","form.keep":"Chúng tôi chỉ dùng thông tin này để trả lời bạn, rồi xóa đi. Không trình theo dõi, không cookie.","form.keepLink":"Chúng tôi giữ những gì","interest.title":"AI-gile: báo cho tôi khi alpha mở","interest.description":"Để lại email để biết khi nào bản alpha hoặc beta kín của AI-gile mở ra.","interest.h1":"🔔 Báo cho tôi khi mở","interest.lede":"AI-gile đang ở giai đoạn tiền alpha kín. Để lại email, chúng tôi sẽ viết đúng một lần, khi có chỗ cho bạn.","interest.email":"Email của bạn","interest.which":"Bản thử nào?","interest.alpha":"Alpha kín: sớm, còn thô, thay đổi nhiều","interest.beta":"Beta: ổn định hơn, muộn hơn","interest.both":"Bản nào đến trước cũng được","interest.submit":"Ghi tên tôi vào danh sách","interest.thanks":"Cảm ơn bạn! Bạn đã có tên trong danh sách.","licence.title":"AI-gile: giấy phép doanh nghiệp","licence.description":"Dùng AI-gile cho công việc kinh doanh? Hãy đăng ký giấy phép doanh nghiệp miễn phí.","licence.h1":"📜 Giấy phép doanh nghiệp","licence.lede":"Dùng AI-gile ở chỗ làm? Hãy cho chúng tôi biết bạn là ai và làm gì. Nếu việc đó mang lại chút điều tốt, giấy phép là miễn phí.","licence.company":"Công ty","licence.website":"Trang web","licence.what":"Bạn làm gì","licence.how":"Nó giúp ích cho thế giới thế nào","licence.email":"Email","licence.submit":"Đăng ký","licence.thanks":"Cảm ơn bạn! Chúng tôi sẽ trả lời qua email.","status.title":"Trạng thái AI-gile","status.h1":"Trạng thái AI-gile","status.quiet":"Mọi thứ yên ắng","status.intro":"AI-gile có đang hoạt động không? Trang này kiểm tra trang web, chia sẻ bảng, cuộc gọi và bản tải xuống mỗi 5 phút.","status.up":"Đang hoạt động (phản hồi trong {ms} ms)","status.slow":"Không phản hồi lần kiểm tra gần nhất, đang thử lại","status.down":"Ngừng hoạt động: không phản hồi hai lần kiểm tra gần nhất","status.svc.web":"Trang web","status.svc.web.offers":"Trang này: AI-gile là gì, và biểu mẫu “Báo cho tôi khi mở”","status.svc.boards":"Chia sẻ bảng","status.svc.boards.offers":"Bảng công khai, tin nhắn giữa bạn bè và lời mời","status.svc.calls":"Cuộc gọi","status.svc.calls.offers":"Thoại, video và chia sẻ màn hình trong AI-gile","status.svc.download":"Tải xuống","status.svc.download.offers":"Bộ cài đặt Windows và liên kết mời","status.checking":"Đang kiểm tra…","status.offline":"Hiện chưa kết nối được dịch vụ trạng thái (đang thử lại)","status.updated":"cập nhật {ago}","status.justNow":"vừa xong","status.min":"{n} phút trước","status.hours":"{n} giờ trước","status.days":"{n} ngày trước","privacy.title":"AI-gile: chúng tôi giữ những gì","privacy.h1":"Chúng tôi giữ những gì","privacy.lede":"Nói ngắn gọn: chỉ những gì bạn gửi cho chúng tôi, và không giữ lâu.","privacy.only":"Chỉ những gì bạn gửi cho chúng tôi: những gì bạn nhập vào biểu mẫu, như email của bạn. Ngoài ra không có gì khác về bạn.","privacy.sealed":"Dữ liệu được niêm phong để máy chủ của chúng tôi không đọc được: ngay trong trình duyệt của bạn trước khi gửi đi (với trình duyệt cũ hơn thì ngay khi đến nơi). Chỉ bảng của chính chúng tôi mới mở được.","privacy.server":"Dữ liệu bị xóa khỏi máy chủ ngay khi đến bảng của chúng tôi. Thứ gì còn sót lại sau 30 ngày cũng sẽ bị xóa.","privacy.board":"Chúng tôi chỉ giữ nó trên bảng cho đến khi đã trả lời bạn, rồi xóa luôn ở đó.","privacy.none":"Không trình theo dõi, không cookie, không phân tích.","privacy.local":"Ngôn ngữ và lựa chọn giao diện sáng hay tối của bạn chỉ nằm trong trình duyệt của bạn. Chúng không bao giờ được gửi cho chúng tôi.","privacy.ask":"Muốn xóa sớm hơn? Hãy trả lời email của chúng tôi và nói vậy.","live.h2":"Xem nó được xây dựng, trực tiếp","live.caption":"Mọi thẻ đều được ẩn: bạn thấy hình dạng của công việc, không phải câu chữ.","live.watching.one":"trực tiếp: {n} người đang xem","live.watching.other":"trực tiếp: {n} người đang xem","live.last.now":"Thẻ cuối cùng vừa được chuyển xong","live.last.min.one":"Thẻ cuối cùng được chuyển {n} phút trước","live.last.min.other":"Thẻ cuối cùng được chuyển {n} phút trước","live.last.hour.one":"Thẻ cuối cùng được chuyển {n} giờ trước","live.last.hour.other":"Thẻ cuối cùng được chuyển {n} giờ trước","live.last.day.one":"Thẻ cuối cùng được chuyển {n} ngày trước","live.last.day.other":"Thẻ cuối cùng được chuyển {n} ngày trước","live.offline":"Bảng trực tiếp đang nghỉ một chút. Hãy quay lại sớm nhé.","live.cols":"Backlog|Cần làm|Đang làm|Nhóm kiểm tra|Bạn cần test|Cho nhóm|Xong"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Agent."]},{"n":2,"texts":["Kanban robot.","Giao agent.","Việc xong."]},{"n":3,"texts":["Kanban cho robot.","Ý thành tính năng.","Kanban agent miễn phí."]},{"n":5,"texts":["Bảng kanban do agent vận hành.","Bạn viết thẻ. Agent làm.","Miễn phí, tại máy, hơi ngộ."]},{"n":8,"texts":["Bảng kanban miễn phí, nơi các agent AI làm việc.","Viết ý tưởng. Agent làm ra. Bạn chấp nhận.","Agile cho một con người và nhiều robot kiên nhẫn."]},{"n":13,"texts":["Một bảng kanban trên máy bạn, nơi các agent AI nhận thẻ về làm.","Viết một ý tưởng. Một nhóm agent làm ra. Người kiểm thử xem lại.","Miễn phí, không tài khoản, không theo dõi: một bảng, vài robot, và bạn làm chủ."]},{"n":21,"texts":["AI-gile là bảng kanban để làm việc cùng các agent lập trình AI. Họ nhận thẻ về làm; bạn thử và chấp nhận chúng.","Mỗi dự án có một trưởng nhóm và các agent AI. Bình luận vào thẻ bất kỳ, cả nhóm bắt tay vào việc.","Một bảng việc cần làm cá nhân, miễn phí, chạy ngay trên máy bạn. Người làm là robot. Người gật đầu là bạn."]},{"n":34,"texts":["Bạn đặt ý tưởng lên bảng. Một nhóm agent AI biến chúng thành tính năng chạy được, kiểm thử, rồi giao lại kèm các bước để thử. Chưa gì được tính là xong cho đến khi bạn nói vậy.","AI-gile là bảng kanban tự chế mà Rich làm với rất nhiều sự giúp đỡ của chính các agent mà nó đang quản lý. Miễn phí, chạy trên máy bạn, và chia sẻ cho bạn bè chứ không bán.","Hình dung một bảng kanban bình thường, với các cột từ Backlog đến Xong, chỉ khác là thẻ do các agent AI nhận làm. Họ báo cáo tiến độ, hỏi khi bị kẹt, và luôn chờ bạn giơ ngón tay cái."]},{"n":55,"texts":["AI-gile là một bảng kanban mà cả nhóm đều là agent AI. Mỗi dự án có một trưởng nhóm lên kế hoạch công việc và những người trợ giúp làm ra nó. Khi một tính năng sẵn sàng, một người kiểm thử AI thử nó và chụp màn hình, rồi nó rơi vào chồng của bạn. Chấp nhận, hoặc bình luận để họ làm lại.","Nó bắt đầu từ cách một người theo dõi cùng lúc thật nhiều phiên lập trình AI, rồi lớn thành một chiếc bảng đúng nghĩa. Nó chạy trên máy bạn, không cần tài khoản, không có trình theo dõi. Miễn phí cho bạn bè và những ai tò mò. Nó cũng chưa xong, nên hãy chờ vài chỗ gồ ghề và đôi bất ngờ.","Đây là phiên bản thành thật. Bạn vẫn phải có ý tưởng, và vẫn phải kiểm tra kết quả. Việc AI-gile làm là mọi thứ ở giữa: giữ các thẻ có thứ tự, đánh thức đúng agent khi bạn bình luận, cho thấy chính xác điều gì đã đổi, và gom tất cả vào một chồng ngắn dành cho bạn."]},{"n":89,"texts":["AI-gile là một bảng kanban miễn phí chạy ngay trên máy tính của bạn. Thay vì con người, mỗi dự án có một nhóm agent AI: một trưởng nhóm biến ý tưởng của bạn thành thẻ và kế hoạch, cùng những người trợ giúp nhận thẻ theo thứ tự ưu tiên. Khi có thứ gì đó làm xong, một người kiểm thử AI làm theo các bước thử và cho bạn xem điều đã thấy. Rồi nó chờ trong một chồng mang tên Cho bạn. Bạn chấp nhận, hoặc bình luận và cả nhóm thử lại. Không có gì đến được cột Xong nếu thiếu bạn.","Có vài tính năng bạn có thể không ngờ tới. Một người gác đêm giữ cột Cần làm luôn đầy khi bạn ngủ, chọn những thẻ không cần bạn trả lời. Bộ đếm token cho thấy các agent đã dùng bao nhiêu hôm nay và tuần này, còn Chế độ Không Token bảo họ ngừng tiêu. Bạn có thể nhắn tin cho bạn bè, và tin nhắn riêng được mã hóa đầu cuối. Bảng nói khoảng 120 ngôn ngữ, gồm tiếng Hà Lan, Flemish, cướp biển và Klingon. Không thứ nào tốn một xu, và cũng chẳng ai đang cố bán gì cho bạn.","AI-gile là một dự án nhỏ, cá nhân, không phải một công ty. Rich muốn trông nom vài dự án lập trình AI mà không phải mở từng ứng dụng ra xem, nên anh và các agent làm một chiếc bảng cho việc đó, rồi dùng chính chiếc bảng ấy để làm nốt phần còn lại. Nó đang ở giai đoạn tiền alpha kín, nghĩa là phần lớn chạy được, cho một nhúm bạn bè. Không có trang bảng giá, không bản tin, không kế hoạch tăng trưởng. Nếu nghe hữu ích, bạn có thể xin thử khi nó mở rộng hơn một chút."]},{"n":144,"texts":["AI-gile là một bảng kanban cho một con người và rất nhiều agent AI. Nó chạy trên máy tính của bạn và hoàn toàn miễn phí. Bạn thêm các dự án, và mỗi dự án có một trưởng nhóm cùng một nhóm nhỏ. Bạn trò chuyện với trưởng nhóm, hơi giống Discord, và mô tả một ý tưởng; trưởng nhóm biến nó thành thẻ và kế hoạch, rồi chờ bạn bấm Bắt đầu. Cả nhóm làm lần lượt các thẻ theo thứ tự ưu tiên, bằng một dòng lệnh đơn giản làm riêng cho các mô hình ngôn ngữ. Trước khi bất cứ thứ gì quay lại với bạn, một người kiểm thử AI làm theo các bước trong một bản sao của ứng dụng và đính kèm ảnh chụp màn hình. Việc xong rơi vào chồng của bạn cùng các tệp đã đổi và phần khác biệt. Bạn chấp nhận, hoặc để lại bình luận và cả nhóm thức dậy làm lại. Chỉ bạn mới chuyển được thẻ sang Xong.","Một ngày với AI-gile, đại khái thế này. Buổi tối bạn để lại vài bình luận: nút này sai chỗ, danh sách kia nên được sắp xếp, có thể thêm chế độ tối không. Bạn đi ngủ. Các agent đọc bình luận, sửa, kiểm thử rồi giao lại cho bạn. Nếu cột Cần làm cạn, người gác đêm sẽ lấy từ backlog những thẻ không cần bạn trả lời để lấp đầy. Sáng ra chỉ có một chồng ngắn: vài câu hỏi và vài thứ để thử, mỗi cái kèm các bước mà người còn ngái ngủ cũng làm theo được và một ảnh chụp màn hình cho thấy nó chạy. Bạn bấm qua, chấp nhận cái tốt và gửi trả phần còn lại. Bộ đếm token cho thấy tất cả tốn bao nhiêu, và Chế độ Không Token dành cho những tuần phải tiết kiệm. Rồi bạn ăn sáng, việc mà các agent chưa giúp được.","Trước hết, AI-gile không phải là gì. Nó không phải công ty khởi nghiệp, không bán, và không ai thu thập dữ liệu của bạn. Nó là một bảng miễn phí chạy trên máy bạn, không tài khoản, không trình theo dõi, không cookie. Còn nó là gì: một nơi gọn gàng để thấy mọi dự án lập trình AI cùng lúc, với một nhóm agent làm thẻ và bạn là người quyết định. Nó gộp các thẻ liên quan, sửa tiêu đề rối, và để mắt xem mã còn gọn đến đâu. Nó nói khoảng 120 ngôn ngữ, từ tiếng Hà Lan và Flemish đến cướp biển và Klingon. Bạn bè có thể nhắn nhau, riêng tư và được mã hóa. Nó do Rich và rất nhiều agent kiên nhẫn làm ra, phần lớn bằng cách tự dùng chính nó. Nó đang ở giai đoạn tiền alpha kín, nên có chỗ còn thô. Nếu nghe vui, hãy hỏi lịch sự, biết đâu bạn vào sớm."]}],"quips":{"1":"Một từ. Táo bạo. Có lẽ hơi quá táo bạo.","3":"Ba từ. Đã thật thà hơn đa số trang sản phẩm.","8":"Tám từ. Vẫn ngắn hơn một buổi họp đứng.","21":"Nhân tiện, các độ dài là story point. Dĩ nhiên rồi.","55":"Năm mươi lăm từ. Trong lúc bạn đọc, hai thẻ đã xong.","144":"Đó là bản dài nhất. Không có 233. Các agent đi ngủ rồi."}},"timeline":{"first-idea.name":"Ý tưởng đầu tiên","first-idea.line":"Cuộc trò chuyện đầu tiên, khi chưa có dòng mã nào.","first-board.name":"Bảng đầu tiên","first-board.line":"Một bảng theo dõi chính quá trình xây nó: thẻ, cột, kéo thả, dự án.","team-roles.name":"Nhóm và vai trò","team-roles.line":"Hồ sơ agent, mẫu nhóm, không gian và ai làm gì.","install.name":"Cài đặt và phát hành","install.line":"Một tệp zip bạn bè cài được, tự cập nhật, các kênh và quay lui.","usage-saver.name":"Tiết kiệm lượt dùng","usage-saver.line":"Đo chi phí mỗi lần chạy, giữ mã gọn nhẹ, giữ hạn mức của bạn.","friends.name":"Bạn bè và chia sẻ","friends.line":"Tin nhắn riêng, máy chuyển tiếp đã xáo trộn, lời mời, vai trò và dự án chung.","languages.name":"Ngôn ngữ","languages.line":"Mọi chữ trên màn hình nằm trong một tệp ngôn ngữ, tiếng Hà Lan và tiếng Flemish trước.","ai-tester.name":"Người kiểm thử AI","ai-tester.line":"Một người kiểm thử xem mọi lần bàn giao trước và cho xem điều đã thấy.","website.name":"Trang web","website.line":"aigile.lol, trang giới thiệu và dòng thời gian này.","streaming.name":"Trò chuyện và phát trực tiếp","streaming.line":"Discord, Twitch, OBS, chế độ streamer, GIF và emoji.","no-ai.name":"Bản không AI","no-ai.line":"Một bảng cho người lập trình không dùng AI, và các bảng công khai.","night-watch.name":"Gác đêm","night-watch.line":"Một người gác và Scrum Master giữ các nhóm đúng việc khi bạn ngủ.","p-more.name":"Mọi thứ còn lại","p-more.line":"Những ý tưởng nhỏ hơn vẫn đang chờ đến lượt.","p-android.name":"Điện thoại và Android","p-android.line":"Vào bảng của bạn từ điện thoại, rồi một ứng dụng Android riêng.","p-release.name":"Alpha và xa hơn","p-release.line":"Alpha kín, trang web chính thức, rồi beta.","p-languages.name":"Thêm ngôn ngữ","p-languages.line":"130 ngôn ngữ, cùng chế độ luyện ngôn ngữ cho người học.","p-engines.name":"Thêm công cụ AI","p-engines.line":"Chọn Claude, Codex, Gemini, Copilot hoặc Cursor cho từng agent.","p-pro.name":"Thực hành chuyên nghiệp","p-pro.line":"Nhãn rủi ro, cổng hợp nhất, thẻ sự cố và rào chắn an toàn.","p-self.name":"Chăm sóc bạn","p-self.line":"Chế độ mệt mỏi, nhắc nhở chăm sóc bản thân và 4:20.","p-servers.name":"Máy chủ và quy mô","p-servers.line":"Cài đặt máy chủ toàn cục, vai trò và kế hoạch để phát triển.","p-livestream.name":"Tiện ích phát trực tiếp","p-livestream.line":"Trò chuyện Twitch, emoji tùy chỉnh và chế độ xem trực tiếp công khai."},"words":{"button":"📖 Thuật ngữ chuyên ngành","h":"📖 Giải thích từ ngữ","intro":"Những từ bạn gặp trong AI-gile, nói bằng lời dễ hiểu: làm ra sản phẩm, thay đổi nó an toàn, giữ cho nó chạy ổn với người dùng, và làm việc như một nhóm cùng AI.","search":"Tìm một từ…","none":"Không có từ nào khớp.","close":"Đóng","count":{"one":"{count} từ","other":"{count} từ"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Làm ra sản phẩm"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Thay đổi an toàn"},{"id":"run","name":"🛎️ Vận hành dịch vụ"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ý tưởng và công việc chưa được lên kế hoạch. Không có gì ở đó được làm cho đến khi chuyển sang Cần làm."},{"id":"sprint","g":"agile","word":"Sprint","text":"Một quãng làm việc ngắn (thường một hoặc hai tuần) với một bộ thẻ đã thống nhất để hoàn thành.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Một buổi cập nhật nhanh: mỗi thành viên đã làm gì, sẽ làm gì tiếp và điều gì đang cản trở.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Một bảng có các cột (Cần làm, Đang làm, Xong) nơi thẻ di chuyển từ trái sang phải khi công việc tiến triển."},{"id":"wip","g":"agile","word":"Giới hạn WIP","text":"Work in progress (việc đang làm): số thẻ tối đa một cột nên chứa, để nhóm làm xong việc trước khi bắt đầu thêm.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Danh sách ngắn của nhóm về thế nào là “xong”, như đã test và đã giải thích, trước khi thẻ được giao cho bạn. Người anh em sinh đôi của nó, Definition of Ready, cho biết khi nào một thẻ đủ rõ để bắt đầu.","also":["Definition of Ready","DoD","DoR","định nghĩa hoàn thành"]},{"id":"retro","g":"agile","word":"Retro","text":"Một lần nhìn lại cách nhóm làm việc, để thống nhất một điều cần làm tốt hơn. Trong AI-gile, retro đề xuất một thay đổi trong cách làm việc của nhóm, và bạn nói Go hoặc Chưa đâu.","also":["retros","retrospective","retrospectives","họp nhìn lại"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Tất cả cùng xắn tay: mọi nhóm gác việc khác để giúp một dự án gấp cho đến khi xong. Trong lúc đó các dự án khác phải chờ.","also":["swarming","dồn lực"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Người giữ cho công việc trôi chảy: phát hiện thẻ bị kẹt, nhắc các nhóm và nhắc bạn những gì đang chờ. Trong AI-gile, Lead Scrum Master làm việc này cho mọi dự án.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Thư mục code của dự án cùng toàn bộ lịch sử commit, thường cũng được giữ trên GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Một nhánh làm việc riêng trong code, để có thể thay đổi mà không đụng đến bản chính.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Một bản chụp đã lưu của code, kèm ghi chú ngắn về điều đã đổi. Bạn luôn có thể quay lại một bản.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Đẩy các bản chụp đã lưu (commit) từ máy này lên GitHub, để chúng được sao lưu và chia sẻ."},{"id":"merge","g":"build","word":"Merge","text":"Nhập các thay đổi của một branch trở lại bản chính."},{"id":"pr","g":"build","word":"Pull request","text":"Yêu cầu kiểm tra các thay đổi của một branch rồi merge vào bản chính.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Dọn dẹp code mà không đổi việc nó làm: tệp nhỏ hơn, tên rõ hơn, bớt lặp lại."},{"id":"bug","g":"build","word":"Bug","text":"Chỗ nào đó không hoạt động đúng như lẽ ra phải thế.","also":["bugs","lỗi"]},{"id":"peerreview","g":"build","word":"Đánh giá ngang hàng","text":"Thêm một đôi mắt: một AI khác kiểm tra công việc của từng thẻ trước khi đến tay bạn, nên ít lỗi lọt qua hơn.","also":["review code","peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Thử một phần việc đã xong để kiểm tra nó làm đúng điều được yêu cầu, trước khi bạn chấp nhận.","also":["tests","kiểm thử"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Viết tắt của quality assurance, tức là đảm bảo chất lượng: các bước kiểm tra tự động chạy trước khi bất cứ thứ gì được đưa vào hoạt động. Khi QA báo đỏ là có gì đó không đạt, và phải sửa xong mới đưa vào hoạt động được.","also":["kiểm tra chất lượng","đảm bảo chất lượng","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"Chồng thử","text":"Các thẻ đã xong đang chờ bạn thử, lần lượt từng cái. Chấp nhận một thẻ hoặc gửi trả kèm ghi chú, và thẻ tiếp theo hiện lên.","also":["test pile","test piles"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Đưa một phiên bản mới lên chạy thật, ví dụ lên máy chủ nơi mọi người dùng."},{"id":"release","g":"change","word":"Bản phát hành","text":"Một gói công việc đã xong, có tên, được đưa vào hoạt động cùng lúc, kèm ghi chú ngắn về những gì đã thay đổi. 🚀 Bản phát hành tự viết ghi chú từ các thẻ đã xong.","also":["phát hành","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Quay lại phiên bản gần nhất còn chạy tốt khi bản mới gây rắc rối. Trong AI-gile, nó tạo một danh sách kiểm tra từ các bước hoàn tác được ghi trên mỗi thay đổi.","also":["quay lại bản cũ","hoàn tác","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"Phiên bản thật mà mọi người đang dùng, khác với bản sao để thử nghiệm. Đưa thứ gì lên đó gọi là đưa vào hoạt động. Lập trình viên còn gọi nó là production.","also":["production","bản chạy thật","môi trường thật"],"noTip":1},{"id":"change","g":"change","word":"Thay đổi","text":"Một thay đổi có kế hoạch cho thứ mà mọi người đang dựa vào, được ghi ra trước: làm gì, vì sao, rủi ro, khi nào và cách hoàn tác. Bắt đầu bằng 🔀 Đề xuất thay đổi.","also":["yêu cầu thay đổi","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Rủi ro","text":"Điều có thể xảy ra sai, được chấm điểm theo khả năng xảy ra và mức độ tệ. ⚠️ Rủi ro gom chúng vào một danh sách, điểm cao nhất lên đầu, mỗi cái có một ngày để xem lại.","also":["các rủi ro","sổ rủi ro","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Khung giờ thay đổi","text":"Những khoảng thời gian được phép đưa thay đổi vào hoạt động, ví dụ một tối thứ Ba yên ắng. Ngoài khung giờ, thẻ thay đổi không thể hoàn tất, trừ khi là trường hợp khẩn cấp.","also":["change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Một lần biểu quyết nhanh ngay trước khi thay đổi được đưa vào hoạt động: mỗi người cần duyệt sẽ nói Go hoặc No go. Chỉ khi mọi người đồng ý thì mới làm tiếp.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Phê duyệt","text":"Chờ một cái gật đầu trước khi bắt đầu làm. Thẻ do bạn bè tạo, hoặc một thay đổi, sẽ chờ trong ✅ Phê duyệt cho đến khi bạn duyệt hoặc từ chối.","also":["duyệt","approval","approvals"]},{"id":"quiettime","g":"change","word":"Giờ yên tĩnh","text":"Một khoảng thời gian, như lúc stream, demo hay ban đêm, khi không đưa gì vào hoạt động. Các nhóm vẫn làm và test bình thường, nhưng việc đưa vào hoạt động phải chờ đến khi hết giờ. Ở nơi khác người ta gọi là change freeze.","also":["đóng băng thay đổi","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Dịch vụ","text":"Thứ bạn làm ra mà mọi người dựa vào, như một trang web hay một ứng dụng, được chăm sóc để luôn chạy tốt. Đánh dấu “Dự án này là một dịch vụ” rồi ghi nó cung cấp gì, ai dùng và ai trực.","also":["các dịch vụ","service","services"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Kiểm tra uptime","text":"Một lần kiểm tra tự động, vài phút một lần, xem dịch vụ của bạn còn phản hồi không. Nếu nó thất bại vài lần liên tiếp, AI-gile tự mở một thẻ sự cố.","also":["uptime","uptime check","uptime checks","thời gian hoạt động"]},{"id":"statuspage","g":"run","word":"Trang trạng thái","text":"Một trang công khai cho biết dịch vụ có đang chạy không (xanh, cam hay đỏ) kèm cập nhật mới nhất, để người dùng tự xem thay vì phải hỏi.","also":["status page","status pages"]},{"id":"desk","g":"run","word":"Bàn dịch vụ","text":"Nơi tiếp nhận câu hỏi và báo cáo từ những người dùng dịch vụ của bạn. AI-gile xếp mỗi cái vào yêu cầu, sự cố hoặc ý tưởng, và báo cho bạn khi nó giống một thứ đã được báo trước đó.","also":["các bàn dịch vụ","bàn hỗ trợ","bàn","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Yêu cầu dịch vụ","text":"Ai đó xin một thứ bình thường, như tài khoản mới hay chút trợ giúp, chứ không phải báo có gì bị hỏng. Nó chờ tới lượt; sự cố luôn được ưu tiên trước.","also":["các yêu cầu dịch vụ","yêu cầu","service request","service requests"]},{"id":"incident","g":"run","word":"Sự cố","text":"Thứ đang hỏng với người dùng ngay lúc này, như trang web bị sập. Thẻ 🔥 sự cố được chen lên đầu hàng: làm cho nó chạy lại là việc đầu tiên.","also":["các sự cố","incident","incidents"]},{"id":"major","g":"run","word":"Sự cố lớn","text":"Một sự cố lớn: nhiều người bị ảnh hưởng, hoặc tiền bạc hay dữ liệu gặp nguy. Một nút bấm đưa mọi nhóm vào cuộc (swarm), đánh thức người đang trực và yêu cầu cập nhật trạng thái mỗi 30 phút.","also":["sự cố nghiêm trọng","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Trực","text":"Là người trả lời khi có gì đó hỏng, kể cả ban đêm. Mỗi dịch vụ có một thành viên trực, người được đánh thức đầu tiên khi dịch vụ đó có sự cố.","also":["trực sự cố","người trực","on call","on-call"]},{"id":"replyby","g":"run","word":"Hạn trả lời","text":"Một thẻ được chờ câu trả lời đầu tiên bao lâu, ví dụ một giờ cho sự cố. Quá hạn thì thẻ hiện đồng hồ đỏ, để không có gì bị lặng lẽ bỏ quên. Còn gọi là response target.","also":["thời hạn trả lời","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Tổng kết sự cố","text":"Một lần nhìn lại ngắn sau sự cố: chuyện gì đã xảy ra, điều gì đã giúp và cần thay đổi gì, không đổ lỗi cho ai. Không có nó thì không đóng được sự cố. Còn gọi là post-mortem.","also":["post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Vấn đề","text":"Nguyên nhân ẩn đằng sau một hay nhiều sự cố. Thẻ 🧩 vấn đề gom những sự cố cứ lặp lại, để tìm ra nguyên nhân và sửa dứt điểm.","also":["các vấn đề","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Nguyên nhân gốc","text":"Lý do thật khiến thứ gì đó hỏng, không chỉ là cái bạn thấy bị lỗi. Sửa nguyên nhân gốc thì sự cố không quay lại nữa.","also":["nguyên nhân gốc rễ","root cause","root causes"]},{"id":"workaround","g":"run","word":"Cách xử lý tạm","text":"Một cách giữ mọi thứ chạy cho đến khi có bản sửa thật, như khởi động lại thứ gì đó khi nó bị treo. Nó được ghi trên thẻ vấn đề để không ai phải tự mò lại.","also":["giải pháp tạm","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Lỗi đã biết","text":"Một vấn đề đã hiểu rõ nguyên nhân và đã có cách xử lý tạm, nhưng chưa được sửa. 🧩 Lỗi đã biết liệt kê chúng, để mọi người dùng cách xử lý tạm thay vì đào bới lại.","also":["các lỗi đã biết","known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Hướng dẫn từng bước để sửa một kiểu rắc rối đã biết, để lần nào cũng làm giống nhau và nhanh. Sau một sự cố lớn, nhóm có thể đề xuất một runbook để bạn duyệt.","also":["runbooks","sổ tay xử lý"]},{"id":"ci","g":"run","word":"Mục cấu hình","text":"Một thứ mà dịch vụ của bạn dựa vào, như máy chủ, tên miền, chứng chỉ, khóa hoặc nhà cung cấp. 🗂️ Mục liệt kê chúng theo từng dịch vụ, để bạn thấy một sự cố ảnh hưởng tới đâu và thứ gì cần gia hạn hoặc sao lưu.","also":["các mục cấu hình","mục","configuration item","configuration items","CI"]},{"id":"expiry","g":"run","word":"Ngày hết hạn","text":"AI-gile để mắt tới các mốc như khi nào chứng chỉ hay tên miền hết hạn. Trong vòng 30 ngày trước mốc đó, nó tạo một thẻ để gia hạn, nên không có gì đột nhiên ngừng chạy.","also":["các ngày hết hạn","hết hạn","theo dõi hết hạn","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"Sao lưu","text":"Một bản sao dữ liệu của bạn được lưu từ trước, để dựa vào nếu có gì bị mất hay hỏng. AI-gile sao lưu các bảng của bạn mỗi ngày.","also":["bản sao lưu","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Khôi phục","text":"Lấy dữ liệu lại từ bản sao lưu. Một bản sao lưu chỉ thật sự có giá trị khi bạn biết nó khôi phục được, nên thỉnh thoảng hãy thử.","also":["đã khôi phục","restore","restored"]},{"id":"svcreview","g":"run","word":"Rà soát dịch vụ","text":"Nhìn lại một tháng của một dịch vụ: sự cố đã mở và đã sửa, mọi người nhận được trả lời nhanh đến đâu, thời gian hoạt động và token đã dùng. Rà soát hàng tháng hiển thị điều này cho từng dịch vụ.","also":["các bản rà soát dịch vụ","rà soát hàng tháng","service review","monthly review"]},{"id":"accessreview","g":"run","word":"Rà soát quyền truy cập","text":"Cứ 90 ngày lại kiểm tra xem ai vẫn còn vào được: liên kết chia sẻ, vai trò của bạn bè và các bí mật đang lưu. Bạn giữ hoặc gỡ từng cái, để quyền truy cập cũ không bị bỏ quên.","also":["các bản rà soát quyền truy cập","access review","access reviews"]},{"id":"improvements","g":"run","word":"Danh sách cải tiến","text":"Mọi điều nhóm đã quyết định làm tốt hơn, gom về một chỗ: đề xuất từ retro, hành động từ các buổi rà soát và các bản sửa vấn đề, mỗi cái kèm trạng thái. Xem ở 📈 Cải tiến.","also":["các danh sách cải tiến","cải tiến","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Hạn mức token","text":"Giới hạn hàng tháng cho số token mà các agent của một dịch vụ được dùng. Ở mức 80% bạn nhận cảnh báo; ở 100% công việc chạy nền của chúng sẽ chờ sang tháng sau hoặc đến khi bạn nâng hạn mức.","also":["các hạn mức token","hạn mức token hàng tháng","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Một AI tự làm việc trên một nhiệm vụ: đọc code, thay đổi, chạy kiểm tra và báo cáo lại.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Đơn vị tính mức dùng AI: xấp xỉ vài chữ cái văn bản được đọc hoặc viết. Càng ít token, gói của bạn càng còn nhiều.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Một lệnh nhỏ tự chạy vào một thời điểm định sẵn, vd. khi một phiên AI bắt đầu, để nhóm nghe được bình luận của bạn.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
